-                    typeRegistry,
-                    s,
-                    typeCap.getType(),
-                    typeCap.getMetricType(),
-                    new TreeMap<>(),
-                    typeCap.isAggregatable(),
-                    isAliasFieldType.get()
-                )
-        );
