+            DataType.DATETIME,
+            DataType.DOUBLE,
+            DataType.FLOAT,
+            DataType.INTEGER,
+            DataType.IP,
+            DataType.KEYWORD,
+            DataType.LONG,
+            DataType.GEO_POINT,
