+
+[source,console]
+--------------------------------------------------
+POST /my-bit-vectors/_search?filter_path=hits.hits
+{
+  "query": {
+    "knn": {
+      "query_vector": [127, -127, 0, 1, 42],
+      "field": "my_vector"
+    }
+  }
+}
