+        transportVersions.getFieldByName("MINIMUM_CCS_VERSION")
+            .orElseThrow(() -> new IllegalStateException("Could not find MINIMUM_CCS_VERSION constant"))
+            .getVariable(0)
+            .setInitializer(new NameExpr(tvConstantName));
+
+        return Optional.of(unit);
+    }
