+            .setMapping("key", "type=keyword", "val", "type=long")
+            .get();
+        ensureGreen(indexName);
+
+        var localCheckpointBeforeBulk = getLocalCheckpointForShard(indexName, 0);
+        fsyncFailureFileSystemProvider.failFSyncOnce(true);
