+    }
+
+    @Override
+    public long skip(long n) throws IOException {
+        assert assertInvariant();
+        final long skipped = super.skip(n);
+        bytesRead += Math.toIntExact(skipped);
+        return skipped;
+    }
+
+    public int getBytesRead() {
+        return bytesRead;
+    }
+
+    protected boolean assertInvariant() {
+        return true;
+    }
+}
